const changes = [
  { who: "L. Marsh", what: "opened search-api for Canary", tone: "text-ok" },
  { who: "bot", what: "held feed-api in Region 1", tone: "text-warn" },
  { who: "L. Marsh", what: "closed billing-api", tone: "text-critical" },
];

export function GateFeed() {
  return (
    <section data-testid="feed" className="p-card rounded-card bg-surface-raised border border-default shadow-raised flex flex-col gap-medium">
      <h2 className="text-heading font-bold text-primary">Recent changes</h2>
      <ul className="flex flex-col divide-y divide-default">
        {changes.map((c) => (
          <li key={c.what} className="flex gap-small py-small text-body">
            <span className="font-medium text-primary">{c.who}</span>
            <span className={c.tone}>{c.what}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}
